### 5. How to Implement a Minimal NuttX I2C Master Driver for RK3506

Based on the patterns above, here is the required structure and implementation outline.

#### File Layout

```
nuttx/arch/arm/src/rk3506/
  rk3506_i2c.h        -- Public API (initialize/uninitialize)
  rk3506_i2c.c        -- Driver implementation
  hardware/
    rk3506_i2c.h      -- Register offset and bit definitions
```

#### Step 1: Register Definitions (`hardware/rk3506_i2c.h`)

Define all register offsets and bit fields as listed in Section 3 above. Use `#define` constants for offsets and bit masks.

#### Step 2: Private Data Structure

```c
struct rk3506_i2c_priv_s
{
  /* MUST be first -- NuttX casts i2c_master_s* to this */
  const struct i2c_ops_s *ops;

  /* Hardware configuration */
  uint32_t base;          /* Peripheral base address */
  uint32_t irq;           /* IRQ number */
  uint32_t clk_id;        /* Clock gate ID */
  uint32_t pclk_id;       /* APB clock gate ID */

  /* Synchronization */
  int refs;               /* Reference count */
  mutex_t lock;           /* Bus mutex */
  sem_t sem_isr;          /* ISR completion semaphore */

  /* Transfer state */
  struct i2c_msg_s *msg;  /* Current message */
  int msg_idx;            /* Current message index */
  int msg_count;          /* Total messages */
  uint8_t *ptr;           /* Current buffer pointer */
  int dcnt;               /* Bytes remaining */
  int processed;          /* Bytes processed */
  uint8_t addr;           /* Current slave address */
  int error;              /* Error code from ISR */
  bool busy;              /* Transfer in progress */
};
```

#### Step 3: Ops Table

```c
static const struct i2c_ops_s rk3506_i2c_ops =
{
  .transfer = rk3506_i2c_transfer,
#ifdef CONFIG_I2C_RESET
  .reset    = rk3506_i2c_reset,
#endif
};
```

#### Step 4: Transfer Function (Polled or IRQ-based)

**IRQ-based approach (recommended, mirrors the Linux driver):**

```c
static int rk3506_i2c_transfer(struct i2c_master_s *dev,
                                struct i2c_msg_s *msgs, int count)
{
  struct rk3506_i2c_priv_s *priv = (struct rk3506_i2c_priv_s *)dev;
  int i, ret = OK;

  nxmutex_lock(&priv->lock);

  for (i = 0; i < count; i++)
    {
      /* 1. Configure REG_MRXADDR with slave address */
      putreg32((msgs[i].addr << 1) | REG_MRXADDR_VALID(0), priv->base + REG_MRXADDR);
      putreg32(0, priv->base + REG_MRXRADDR);

      /* 2. Set mode: TX or REGISTER_TX (for reads) */
      if (msgs[i].flags & I2C_M_READ)
        {
          putreg32((msgs[i].addr << 1) | 1 | REG_MRXADDR_VALID(0),
                   priv->base + REG_MRXADDR);
          priv->mode = REG_CON_MOD_REGISTER_TX;
        }
      else
        {
          priv->mode = REG_CON_MOD_TX;
        }

      /* 3. Fill TX buffer (for writes) or set RX count (for reads) */
      priv->msg = &msgs[i];
      priv->processed = 0;
      priv->busy = true;

      if (!(msgs[i].flags & I2C_M_READ))
        rk3506_i2c_fill_txbuf(priv);

      /* 4. Enable interrupts and start */
      putreg32(REG_INT_MBTF | REG_INT_MBRF | REG_INT_NAKRCV | REG_INT_STOP,
               priv->base + REG_IEN);
      putreg32(REG_CON_EN | REG_CON_MOD(priv->mode) | REG_CON_START |
               REG_CON_ACTACK, priv->base + REG_CON);

      /* 5. For reads, set MRXCNT */
      if (msgs[i].flags & I2C_M_READ)
        putreg32(msgs[i].length > 32 ? 32 : msgs[i].length,
                 priv->base + REG_MRXCNT);
      else
        putreg32(/* byte count */, priv->base + REG_MTXCNT);

      /* 6. Wait for ISR to signal completion */
      ret = nxsem_tickwait(&priv->sem_isr, MSEC2TICK(500));
      if (ret < 0 || priv->error)
        {
          /* Timeout: force STOP */
          putreg32(0, priv->base + REG_IEN);
          uint32_t con = getreg32(priv->base + REG_CON) & REG_CON_TUNING_MASK;
          con |= REG_CON_EN | REG_CON_STOP;
          putreg32(con, priv->base + REG_CON);
          ret = ret < 0 ? -ETIMEDOUT : priv->error;
          break;
        }

      /* 7. Handle repeated-start vs STOP */
      bool is_last = (i == count - 1);
      bool next_is_restart = !is_last && !(msgs[i].flags & I2C_M_NOSTOP);

      if (is_last || next_is_restart)
        {
          /* Issue STOP (the ISR already does this for the last msg) */
        }
      /* If NOSTOP, the next iteration will issue repeated START */
    }

  /* Disable controller */
  uint32_t con = getreg32(priv->base + REG_CON) & REG_CON_TUNING_MASK;
  putreg32(con, priv->base + REG_CON);

  nxmutex_unlock(&priv->lock);
  return ret;
}
```

#### Step 5: ISR Handler

```c
static int rk3506_i2c_isr(int irq, void *context, void *arg)
{
  struct rk3506_i2c_priv_s *priv = (struct rk3506_i2c_priv_s *)arg;
  uint32_t ipd = getreg32(priv->base + REG_IPD);

  /* Handle NACK */
  if (ipd & REG_INT_NAKRCV)
    {
      putreg32(REG_INT_NAKRCV, priv->base + REG_IPD);
      priv->error = -ENXIO;
      rk3506_i2c_stop(priv);
      return OK;
    }

  /* Handle TX complete */
  if (ipd & REG_INT_MBTF)
    {
      putreg32(REG_INT_MBTF, priv->base + REG_IPD);
      if (priv->processed >= priv->msg->length)
        rk3506_i2c_stop(priv);
      else
        rk3506_i2c_fill_txbuf(priv);
    }

  /* Handle RX complete */
  if (ipd & REG_INT_MBRF)
    {
      putreg32(REG_INT_MBRF | REG_INT_START, priv->base + REG_IPD);
      rk3506_i2c_read_rxbuf(priv);
      if (priv->processed >= priv->msg->length)
        rk3506_i2c_stop(priv);
      else
        rk3506_i2c_prepare_read(priv);
    }

  /* Handle STOP */
  if (ipd & REG_INT_STOP)
    {
      putreg32(REG_INT_STOP, priv->base + REG_IPD);
      priv->busy = false;
      nxsem_post(&priv->sem_isr);
    }

  return OK;
}
```

#### Step 6: Clock/Divisor Setup

```c
static void rk3506_i2c_setclock(struct rk3506_i2c_priv_s *priv, uint32_t freq)
{
  uint32_t clk_rate = rk3506_get_i2c_clk_rate(priv);
  uint32_t div_low, div_high;

  /* For standard mode (100kHz) with a ~100MHz input clock:
   *   div_total = clk_rate / (freq * 8)
   *   div_low  = div_total * 0.55 - 1
   *   div_high = div_total * 0.45 - 1
   *
   * For fast mode (400kHz): same formula, smaller dividers.
   * Use the v1_calc_timings algorithm from i2c-rk3x.c for precision.
   */

  /* Simplified: assume 100MHz clock, 100kHz SCL */
  uint32_t total = clk_rate / (freq * 8);
  div_low  = (total * 55 / 100) - 1;
  div_high = (total * 45 / 100) - 1;

  putreg32((div_high << 16) | (div_low & 0xffff), priv->base + REG_CLKDIV);
}
