struct i2c_master_s *rk3506_i2cbus_initialize(int port)
{
  struct rk3506_i2c_priv_s *priv;

  switch (port)
    {
      case 0: priv = &g_rk3506_i2c0_priv; break;
      case 1: priv = &g_rk3506_i2c1_priv; break;
      case 2: priv = &g_rk3506_i2c2_priv; break;
      default: return NULL;
    }

  nxmutex_lock(&priv->lock);
  if (priv->refs++ == 0)
    {
      /* Enable clocks, configure GPIO pins, attach ISR */
      rk3506_i2c_init(priv);
    }
  nxmutex_unlock(&priv->lock);

  return (struct i2c_master_s *)priv;
}
